const E=My3D2dge,$=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(v,prec=0)=>(v<0?'−':'')+'$'+Math.abs(v).toLocaleString('en-US',{minimumFractionDigits:prec,maximumFractionDigits:prec})+'k';
const months=['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'];
const date=m=>months[Math.floor(m)%12]+' '+(1890+Math.floor(m/12));
const paths={overview:'M3 10l9-7 9 7M5 9v12h14V9M9 21v-8h6v8',build:'M7 2v20M17 2v20M4 5h16M4 12h16M4 19h16',routes:'M5 4a2 2 0 1 0 0 .1M19 18a2 2 0 1 0 0 .1M5 6v6h14v4',trains:'M6 4h12l2 12H4ZM7 4V2h10v2M7 9h10M8 16l-3 6M16 16l3 6M7 20h10M7 13h1M16 13h1',industry:'M3 21V9l6 4V8l6 4V3h4l2 18ZM6 17h1M11 17h1M16 17h1',company:'M3 21h18M5 21V9M10 21V9M14 21V9M19 21V9M3 8h18L12 2ZM4 5h16',goals:'M8 3h8v8a4 4 0 0 1-8 0ZM8 5H4v3a4 4 0 0 0 4 4M16 5h4v3a4 4 0 0 1-4 4M12 15v5M7 22h10M9 20h6',help:'M9 8a3 3 0 1 1 5 2c-2 1-2 2-2 4M12 18h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3l1-2h4l1 2 2 1 2-1 2 3-1 2v3l2 1v4l-2 1-1 2v2l-3 1-2-1h-3l-2 1-3-2v-2l-2-2H2v-4l2-1V8L3 6l3-3 2 1Z',leaf:'M20 3C8 2 2 8 4 15c3 7 15 5 16-12ZM4 21L15 9',arrow:'M5 12h14M14 7l5 5-5 5',save:'M4 3h14l3 3v15H3V3ZM7 3v6h10V3M7 21v-8h10v8',sound:'M3 9h4l5-5v16l-5-5H3ZM16 8a6 6 0 0 1 0 8M19 4a11 11 0 0 1 0 16'};
const icon=(name)=>'<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="'+(paths[name]||paths.overview)+'"/></svg>';
$('settings-button').innerHTML=icon('settings');
const tabs=[['overview','Charter'],['build','Build'],['routes','Railways'],['trains','Trains'],['industry','Industry'],['company','Company'],['goals','Awards'],['help','Guide']];
$('toolrail').innerHTML=tabs.map(([id,label])=>'<button data-tab="'+id+'" title="'+label+'" class="'+(id==='overview'?'active':'')+(id==='help'?' rail-bottom':'')+'">'+icon(id)+'<span>'+label+'</span></button>').join('');
let sim=new Railway();
const game=new E.Game({canvas:'world',res:null,minW:100000,minH:100000,maxW:4096,maxH:4096,input:{},view:'iso',bg:'#bfd4c5',step:1/60});game.pauseOverlay=false;
const world=new ValleyWorld(game,()=>sim);
let settings=E.store.get('copperline-settings-v1',{mode:'standard',gpu:true,bands:10,edge:.8,pixel:4,dither:.18,saturation:1.05,strength:.75,volume:.4,music:true,effects:true,reduced:matchMedia('(prefers-reduced-motion:reduce)').matches});
const ui={started:false,tab:'overview',selected:null,selectedTrain:null,from:null,to:null,policy:'valley',speed:1,paused:true,modal:null,dirty:true,showGuide:true,outcomeShown:false,saveAge:0,panelTimer:0,acc:0,lastMedal:null,previousFocus:null};
const filter=new ArtFilter($('world'),$('gpu-world'),(backend,note)=>{const el=$('render-status');if(el)el.textContent='Active renderer: '+backend+'. '+note;$('world').dataset.renderer=backend;$('world').dataset.filterError=filter.error||'';});
const labelCanvas=document.createElement('canvas');labelCanvas.className='label-canvas';labelCanvas.setAttribute('aria-hidden','true');$('gpu-world').after(labelCanvas);world.externalLabels=true;
const origPresent=game.screen.present.bind(game.screen);game.screen.present=()=>{origPresent();filter.render();const s=game.screen;if(labelCanvas.width!==s.canvas.width||labelCanvas.height!==s.canvas.height){labelCanvas.width=s.canvas.width;labelCanvas.height=s.canvas.height;}const g=labelCanvas.getContext('2d');g.clearRect(0,0,labelCanvas.width,labelCanvas.height);if(ui.started){g.save();g.translate(s.OX-Math.round(s.fx*s.S),s.OY-Math.round(s.fy*s.S));g.scale(s.S,s.S);world.drawLabels(g,game.r,sim);g.restore();}};
const score={bpm:76,steps:2,tracks:[{wave:'sine',vol:.1,notes:'D5 - - A4 - - F#4 - | G4 - - B4 - - A4 - | F#4 - D4 - E4 - A4 - | D5 - - - - - . . | B4 - - A4 - F#4 - | G4 - B4 - D5 - - - | E5 - D5 - B4 - A4 - | D5 - - - - - . .'}, {wave:'triangle',vol:.12,notes:'D3 - A3 - D4 - A3 - | G2 - D3 - G3 - D3 - | A2 - E3 - A3 - E3 - | D3 - A3 - D4 - A3 - | B2 - F#3 - B3 - F#3 - | G2 - D3 - G3 - D3 - | A2 - E3 - A3 - E3 - | D3 - A3 - D4 - A3 -'}]};
function applySettings(){game.audio.setVolume(settings.volume);world.reduced=!!settings.reduced;game.reduceMotion=world.reduced;document.body.classList.toggle('reduce-motion',world.reduced);filter.apply(settings);E.store.set('copperline-settings-v1',settings);if(ui.started){if(settings.music)game.audio.music(score);else game.audio.music(null);}}
const sfx=(name='confirm',volume=.3)=>{if(settings.effects)game.audio.sfx(name,{vol:volume});};
function toast(title,text,type='info'){const el=document.createElement('div');el.className='toast '+type;el.innerHTML='<strong>'+esc(title)+'</strong><p>'+esc(text)+'</p>';$('toast-stack').prepend(el);while($('toast-stack').children.length>3)$('toast-stack').lastChild.remove();setTimeout(()=>el.remove(),6000);}
function act(fn){try{const result=fn();sfx();ui.dirty=true;updateUI(true);return result;}catch(e){sfx('cancel');toast('Action not available',e.message,'warning');return null;}}
const head=(kicker,title,text='')=>'<div class="panel-header"><span class="eyebrow">'+kicker+'</span><h2>'+title+'</h2>'+(text?'<p>'+text+'</p>':'')+'</div>';
const section=(title,content)=>'<section class="panel-section">'+(title?'<h3>'+title+'</h3>':'')+content+'</section>';
const btn=(action,text,style='primary',attrs='')=>'<button class="'+style+' full" data-action="'+action+'" '+attrs+'>'+text+'</button>';
const stat=(name,value,cls='')=>'<div class="stat-row"><span>'+name+'</span><strong class="'+cls+'">'+value+'</strong></div>';
const empty=(title,text,id='trains')=>'<div class="empty">'+icon(id)+'<h3>'+title+'</h3><p>'+text+'</p></div>';
function goalHTML(goal){const done=goal.value>=goal.target;return '<div class="goal '+(done?'done':'')+'"><div class="goal-heading"><span>'+(done?'✓ ':'')+esc(goal.label)+'</span><span>'+Math.max(0,Math.floor(goal.value))+' / '+goal.target+'</span></div><div class="progress"><i style="width:'+clamp(goal.value/goal.target*100,0,100)+'%"></i></div></div>';}
function renderPanel(){
 document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===ui.tab));world.mode=ui.tab==='build'?'build':'inspect';$('world').classList.toggle('building',ui.tab==='build');
 let html='';const goals=sim.goals(),medal=sim.medal();
 if(ui.tab==='site'&&ui.selected){html=sitePanel(sim.site(ui.selected));}
 else if(ui.tab==='train'&&ui.selectedTrain){const t=sim.trains.find(t=>t.id===ui.selectedTrain);html=t?trainPanel(t):head('LOCOMOTIVE ROSTER','Train sold');}
 else if(ui.tab==='overview'){
  html=head('SCENARIO 01 · 1890–1900','The Valley Charter','Build a working railway before the new century.');
  html+=section('Your charter',goals.bronze.map(goalHTML).join('')+'<div class="objective-summary">'+(medal?'<strong>'+medal.toUpperCase()+' AWARD READY</strong><br>Claim the charter now, or keep building for a higher award.':Math.max(0,120-Math.floor(sim.month))+' months remain. Keep cash above zero when you claim your charter.')+'</div>'+(medal?btn('claim','Claim '+medal+' charter'):btn('tab-build',icon('build')+' Survey a railway')));
  if(ui.showGuide){const steps=[{done:sim.routes.length>0,title:'Link the valley towns',text:'Start with Cedar Junction and Millbrook. The survey includes station costs.'},{done:sim.trains.length>0,title:'Put a train to work',text:'Buy a Pioneer. Select both towns and use automatic cargo.'},{done:(sim.delivered.passengers||0)>0,title:'Start the clock',text:'Watch the first delivery pay for the next connection.'}];html+=section('First steps',steps.map((s,i)=>'<div class="guide-step '+(s.done?'done':'')+'"><span class="step-num">'+(s.done?'✓':i+1)+'</span><div><strong>'+s.title+'</strong><p>'+s.text+'</p></div></div>').join('')+'<button class="link-button" data-action="hide-guide">Hide first steps</button>');}
  const event=EVENTS.find(e=>sim.month<e.end);if(event)html+=section('Valley dispatch','<span class="small-label">'+date(event.at)+' – '+date(event.end)+'</span><div class="event-strip"><strong>'+event.title+'</strong><br>'+event.text+'</div>');
 }
 else if(ui.tab==='build'){
  html=head('ENGINEERING OFFICE','Survey a railway','Choose two map labels or use the site list. Inspect the full cost before you build.');
  const opts=(selected)=>'<option value="">Select a destination</option>'+sim.sites.map(s=>'<option value="'+s.id+'" '+(selected===s.id?'selected':'')+'>'+s.name+(s.station?' · station':'')+'</option>').join('');
  html+=section('', '<label class="field"><span>Starting site</span><select id="build-from">'+opts(ui.from)+'</select></label><label class="field"><span>Destination</span><select id="build-to">'+opts(ui.to)+'</select></label><div class="segmented"><button data-policy="valley" class="'+(ui.policy==='valley'?'selected':'')+'">Follow the valley</button><button data-policy="direct" class="'+(ui.policy==='direct'?'selected':'')+'">Direct route</button></div><p class="inline-note">Valley routes avoid steep ground. Direct routes can cost more in cuttings.</p>');
  if(world.quote){const q=world.quote;html+=section('Survey estimate',stat('Track length',q.length.toFixed(1)+' km')+stat('River spans',q.bridges)+stat('Rock cuttings',q.tunnels)+stat('Average grade',q.grade.toFixed(1)+'%')+stat('Track and structures',money(q.railCost,1))+stat('New stations',money(q.stationCost))+'<div class="cost-total"><span>Total construction</span><strong>'+money(q.cost,1)+'</strong></div>'+btn('build-route','Lay railway · '+money(q.cost,1),'primary',q.cost>sim.cash?'disabled':'')+'<p class="data-note">Stations at both ends are included. The survey follows buildable cells. You can extend this network later.</p>');}
  else html+=section('',empty('A line on the map','Choose the first site, then choose its destination. The survey will appear in gold.','build'));
 }
 else if(ui.tab==='routes'){
  html=head('ENGINEERING OFFICE','Your railways',sim.routes.length+' routes · '+sim.routes.reduce((a,r)=>a+r.length,0).toFixed(1)+' km of railway.');
  html+=section('',sim.routes.length?'<div class="route-list">'+sim.routes.map(r=>'<div class="list-card"><div class="card-top"><strong>'+esc(sim.site(r.from).name)+'</strong></div><p>to '+esc(sim.site(r.to).name)+'</p><div class="card-metric"><span>'+r.length.toFixed(1)+' km</span><span>'+(r.double?'DOUBLE TRACK':'SINGLE TRACK')+'</span></div><div class="button-row">'+(!r.double?'<button class="mini-btn" data-double="'+r.id+'">Double · '+money(Math.round(r.railCost*.65))+'</button>':'<span class="inline-note">Two-way capacity</span>')+'<button class="mini-btn" data-remove-route="'+r.id+'">Remove</button></div></div>').join('')+'</div>':empty('The map is waiting','Survey a connection to start your network.','build'));html+=section('',btn('tab-build','Survey another route'));
 }
 else if(ui.tab==='trains'){
  html=head('LOCOMOTIVE ROSTER','Your trains',sim.trains.length+' engines · '+sim.trains.reduce((a,t)=>a+t.trips,0)+' paid deliveries.');
  html+=section('',btn('buy-train',icon('trains')+' Buy a locomotive')+'<p class="inline-note">Every train needs at least two connected stations.</p>');
  html+=section('',sim.trains.length?'<div class="train-list">'+sim.trains.map(t=>'<button class="list-card" data-train="'+t.id+'"><div class="card-top"><strong>'+esc(t.name)+'</strong><span class="tag">'+status(t)+'</span></div><p>'+t.stops.map(id=>esc(sim.site(id).name)).join(' · ')+'</p><div class="card-metric"><span>'+t.cars+' cars · '+Math.floor(t.condition)+'% condition</span><span class="'+(t.revenue-t.costs>=0?'positive':'negative')+'">'+money(t.revenue-t.costs)+'</span></div></button>').join('')+'</div>':empty('Steam belongs here','Buy your first engine after you build a railway.'));
 }
 else if(ui.tab==='industry'){
  html=head('VALLEY ECONOMY','Goods & industries','Raw goods become valuable cargo when you complete a production chain.');
  html+=section('Production chains','<div class="tip"><strong>Highpine → Pineworks → Port</strong><br>Logs → lumber → export income.</div><div class="tip"><strong>Sunfield → Millbrook → Towns</strong><br>Grain → food → market income.</div><div class="tip"><strong>Copper Ridge → Foundry → Port</strong><br>Ore → copper → export income.</div>');
  html+=section('Industry directory','<div class="site-list">'+sim.sites.filter(s=>s.process||!s.pop).map(s=>'<button class="list-card" data-site="'+s.id+'"><div class="card-top"><strong>'+s.name+'</strong><span class="tag">'+(s.owned?'OWNED':s.station?'CONNECTED':'NO STATION')+'</span></div><p>'+Object.keys(s.produces).concat(s.process?[s.process.output]:[]).map(k=>GOODS[k].name+': '+Math.floor(s.stock[k])).join(' · ')+'</p></button>').join('')+'</div>');
 }
 else if(ui.tab==='company')html=companyPanel();
 else if(ui.tab==='goals'){
  html=head('THE CHARTER OFFICE','Three levels of success','Higher awards include all lower award goals. Finish with cash at zero or above.');
  for(const [id,title]of [['bronze','Bronze · A working railway'],['silver','Silver · A growing valley'],['gold','Gold · A lasting company']])html+=section('', '<div class="medal-title"><h3>'+title+'</h3>'+icon('goals')+'</div>'+goals[id].map(goalHTML).join(''));
  html+=section('',btn('claim',medal?'Claim '+medal+' charter':'Complete the bronze goals','primary',!medal?'disabled':'')+'<p class="data-note">The charter closes in January 1900. You can continue in free play after the result.</p>');
  html+=section('Bonus contracts',CONTRACTS.map(c=>{const n=c.to?sim.deliveredTo[c.to+':'+c.cargo]||0:sim.delivered[c.cargo]||0;return '<div class="contract-card"><h3>'+c.title+'</h3><p>'+c.text+'</p><div class="stat-row"><span>'+Math.min(n,c.target)+' / '+c.target+'</span><span class="reward">'+(sim.contracts.includes(c.id)?'✓ Paid':money(c.reward))+'</span></div></div>';}).join(''));
 }
 $('panel-content').innerHTML=html;
 if(ui.tab==='company')drawChart();
 $('map-hint').textContent=ui.tab==='build'?(ui.from?(ui.to?'Inspect the survey, then lay the railway.':'Select a destination on the map.'):'Select a starting site on the map.'):world.follow?'Following a train · drag to release':ui.paused&&sim.trains.length?'Time is paused · press Space to run the railway':'';
 ui.dirty=false;
}
function sitePanel(s){if(!s)return '';world.selected=s.id;const produce=Object.keys(s.produces).concat(s.process?[s.process.output]:[]);
 let html=head(s.tag,s.name,s.description);
 html+=section('Station',stat('Status',s.station?'Level '+s.station+' station':'No station')+stat('Service depot',s.service?'Open':'Not built')+(s.pop?stat('Population',s.pop.toLocaleString()):'')+(s.station?'<div class="button-row">'+(s.station<3?'<button class="secondary" data-upgrade-station="'+s.id+'">Expand · '+money(s.station===1?30:45)+'</button>':'')+(!s.service?'<button class="secondary" data-service-site="'+s.id+'">Depot · $22k</button>':'')+'</div>':btn('station','Build station · $24k','secondary','data-id="'+s.id+'"'))+btn('connect-site','Connect this site','primary','data-id="'+s.id+'"'));
 html+=section('Available cargo',produce.length?produce.map(k=>'<div class="cargo-item"><span><i class="cargo-dot" style="background:'+GOODS[k].color+'"></i>'+GOODS[k].name+'</span><strong>'+Math.floor(s.stock[k])+' <small>cars</small></strong></div>').join(''):'<p>No cargo is produced here.</p>');
 if(s.accepts.length)html+=section('Demand',s.accepts.map(k=>'<div class="cargo-item"><span><i class="cargo-dot" style="background:'+GOODS[k].color+'"></i>'+GOODS[k].name+'</span><strong>'+Math.round((s.demand[k]||1)*100)+'%</strong></div>').join('')+'<p class="fineprint">Fees fall after heavy deliveries. Demand recovers over time.</p>');
 if(s.process)html+=section('Processing',stat('Input waiting',Math.floor(s.inputs[s.process.input]||0)+' '+GOODS[s.process.input].name.toLowerCase())+stat('Monthly capacity',(s.process.rate*s.boost).toFixed(1)+' input cars')+'<p>'+GOODS[s.process.input].name+' becomes '+GOODS[s.process.output].name.toLowerCase()+'. Empty output stock means more inputs are needed.</p>');
 if(!s.pop)html+=section('Industry ownership',s.owned?'<p>Your company receives production income from this industry.</p>'+(!s.boost||s.boost===1?btn('expand-industry','Expand output · $60k','secondary','data-id="'+s.id+'"'):'<div class="tip">Production capacity is 75% higher.</div>'):'<p>Buy this industry to receive production income and expand its capacity.</p>'+btn('buy-industry','Buy industry · '+money(s.process?110:85),'secondary','data-id="'+s.id+'"'));
 return html;
}
function status(t){return t.hold?'Held':({running:'En route',loading:'Loading',signal:'Signal wait',service:'Servicing',blocked:'No route'}[t.state]||t.state);}
function trainPanel(t){const engine=ENGINES[t.engine],from=sim.site(t.stops[t.stopIndex]),to=sim.site(t.stops[(t.stopIndex+1)%t.stops.length]);
 return head(engine.class.toUpperCase(),esc(t.name),engine.name)+section('Current journey',stat('Status',status(t))+stat('From',from.name)+stat('To',to.name)+'<div class="progress"><i style="width:'+clamp(t.progress/Math.max(1,t.journey?.length||1)*100,0,100)+'%"></i></div><div class="button-row"><button class="secondary" data-follow="'+t.id+'">'+(world.follow===t.id?'Stop following':'Follow train')+'</button><button class="secondary" data-hold="'+t.id+'">'+(t.hold?'Release train':'Hold train')+'</button></div>'+(t.state==='signal'?'<div class="tip">Waiting for a single-track section to clear. Double track increases capacity.</div>':''))+section('Cargo on board',t.load.length?t.load.map(l=>'<div class="cargo-item"><span><i class="cargo-dot" style="background:'+GOODS[l.cargo].color+'"></i>'+GOODS[l.cargo].name+'</span><strong>'+l.amount+' cars</strong></div>').join(''):'<p>The cars are empty. Automatic cargo loads goods that the next stop accepts.</p>')+section('Performance',stat('Condition',Math.floor(t.condition)+'%',t.condition<40?'negative':'')+stat('Paid deliveries',t.trips)+stat('Revenue',money(t.revenue,1),'positive')+stat('Running costs',money(t.costs,1))+stat('Operating profit',money(t.revenue-t.costs,1),t.revenue>=t.costs?'positive':'negative')+stat('Loaded travel',Math.round(t.loadedMiles/Math.max(1,t.loadedMiles+t.emptyMiles)*100)+'%')+'<div class="train-controls"><button class="secondary" data-service-train="'+t.id+'">Service · $5k</button><button class="secondary" data-orders="'+t.id+'">Edit orders</button></div>'+(t.pending?'<p class="tip">New orders will start at the next shared stop.</p>':''))+section('Route plan',t.stops.map((id,i)=>stat('Stop '+(i+1),sim.site(id).name)).join('')+stat('Cargo',t.cargo==='auto'?'Automatic':GOODS[t.cargo].name)+stat('Depart with',{any:'Any cargo',half:'Half load',full:'Full load'}[t.wait])+'<p class="fineprint">Maximum loading wait: one month. Trains then depart to avoid a stalled service.</p>')+section('',btn('sell-train','Sell this engine','danger-btn','data-id="'+t.id+'"'));
}
function companyPanel(){return head('COPPERLINE RAILWAY CO.','Company ledger','Capital buys the network. Operating profit measures traffic and industry income after costs.')+section('Company accounts',stat('Cash',money(sim.cash,1),sim.cash<0?'negative':'')+stat('Company value',money(sim.companyValue))+stat('Revenue',money(sim.revenue,1),'positive')+stat('Operating costs',money(sim.expenses,1))+stat('Operating profit',money(sim.profit,1),sim.profit>=0?'positive':'negative')+stat('Contract grants',money(sim.grants))+stat('Last month cash income',money(sim.lastRevenue,1))+stat('Last month costs',money(sim.lastExpenses,1))+'<canvas class="sparkline" id="cash-chart" width="500" height="140" aria-label="Monthly cash balance chart"></canvas>')+section('Debt & funding',stat('Bond debt',money(sim.debt))+stat('Annual interest',money(sim.debt*.06,1))+stat('Debt limit','$500k')+'<div class="button-row"><button class="secondary" data-action="bond" '+(sim.debt>=500?'disabled':'')+'>Issue $100k</button><button class="secondary" data-action="repay" '+(sim.debt<100||sim.cash<100?'disabled':'')+'>Repay $100k</button></div><p class="data-note">Bonds cost 6% a year. Interest is charged each month.</p>')+section('Shares & your account',stat('Share price',money(sim.stockPrice,2))+stat('Your ownership',Math.round(sim.playerShares/sim.shares*100)+'%')+stat('Your shares',sim.playerShares+' / '+sim.shares)+stat('Personal cash',money(sim.personalCash,1))+'<div class="button-row"><button class="secondary" data-action="buy-shares">Buy 5 shares</button><button class="secondary" data-action="sell-shares">Sell 5 shares</button></div>'+btn('issue-shares','Issue 10 company shares','secondary',sim.shares>=160?'disabled':'')+'<label class="field"><span>Annual dividend rate</span><select id="dividend"><option value="0" '+(!sim.dividend?'selected':'')+'>No dividend</option><option value="0.005" '+(sim.dividend===.005?'selected':'')+'>0.5% of share value</option><option value="0.015" '+(sim.dividend===.015?'selected':'')+'>1.5% of share value</option></select></label><p class="data-note">Company cash and personal cash are separate. Selling your shares does not fund the railway. New share issues fund the company and reduce your ownership percentage.</p>');}
function drawChart(){const cv=$('cash-chart');if(!cv)return;const g=cv.getContext('2d'),history=sim.history.slice(-24);g.clearRect(0,0,cv.width,cv.height);if(history.length<2){g.fillStyle='#a0b496';g.font='20px Arial';g.textAlign='center';g.fillText('Cash history starts after one month.',250,80);return;}const max=Math.max(...history.map(x=>x.cash),1),min=Math.min(...history.map(x=>x.cash),0),range=Math.max(1,max-min);g.strokeStyle='#d5bb85';g.lineWidth=3;g.beginPath();history.forEach((p,i)=>{const x=i/(history.length-1)*480+10,y=120-(p.cash-min)/range*110;if(i)g.lineTo(x,y);else g.moveTo(x,y);});g.stroke();g.lineTo(490,135);g.lineTo(10,135);g.closePath();g.fillStyle='#d5bb8514';g.fill();}
function selectTab(tab){if(tab==='help'){showHelp();return;}ui.tab=tab;ui.selected=null;world.selected=null;world.quote=null;world.follow=null;if(tab==='build')updateSurvey();ui.dirty=true;renderPanel();}
function selectSite(id){if(ui.tab==='build'){if(!ui.from||ui.to){ui.from=id;ui.to=null;}else if(id!==ui.from)ui.to=id;updateSurvey();}else{ui.selected=id;ui.tab='site';world.selected=id;}ui.dirty=true;renderPanel();sfx('select',.15);}
function selectTrain(id){ui.selectedTrain=id;ui.tab='train';world.quote=null;world.selected=null;ui.dirty=true;renderPanel();}
function updateSurvey(){world.quote=null;if(ui.from&&ui.to){try{world.quote=sim.survey(ui.from,ui.to,ui.policy);}catch(e){toast('Survey notice',e.message,'warning');}}world.selected=ui.from;ui.dirty=true;}
function updateUI(force=false){$('cash').textContent=money(sim.cash);$('cash').classList.toggle('negative',sim.cash<0);$('profit').textContent=money(sim.profit);$('profit').classList.toggle('negative',sim.profit<0);$('network').innerHTML=sim.connected.length+' / 8 <small>sites</small>';$('date').textContent=date(sim.month);const mon=Math.floor(sim.month)%12;$('season').textContent=['Winter','Winter','Spring','Spring','Spring','Summer','Summer','Summer','Autumn','Autumn','Autumn','Winter'][mon]+' · Year '+Math.min(10,1+Math.floor(sim.month/12))+' of 10';const paused=ui.paused||!!ui.modal||!ui.started||!!sim.result;$('pause-label').textContent=paused?'PAUSED':ui.speed+'× SPEED';$('pause-button').textContent=paused?'▶':'Ⅱ';$('pause-button').setAttribute('aria-label',ui.paused?'Start time':'Pause time');document.querySelectorAll('[data-speed]').forEach(b=>b.classList.toggle('active',+b.dataset.speed===ui.speed));const running=sim.trains.filter(t=>t.state==='running'&&!t.hold).length;$('status-message').textContent=sim.trains.length?running+' engines in motion · '+sim.trains.filter(t=>t.state==='signal').length+' at signals':'Survey. Build. Connect.';
 if(force||ui.dirty){const focus=document.activeElement;const editing=$('inspector').contains(focus)&&['INPUT','SELECT'].includes(focus.tagName);if(!editing||force)renderPanel();}world.drawMinimap($('minimap'));}
function openDialog(title,html,kicker='COPPERLINE'){ui.previousFocus=document.activeElement;ui.modal=title;$('dialog-title').textContent=title;$('dialog-kicker').textContent=kicker;$('dialog-body').innerHTML=html;if(!$('dialog').open)$('dialog').showModal();updateUI();}
function closeDialog(){if($('dialog').open)$('dialog').close();ui.modal=null;ui.previousFocus?.focus?.();ui.previousFocus=null;ui.dirty=true;updateUI();}
$('dialog').addEventListener('cancel',()=>{ui.modal=null;ui.dirty=true;});$('dialog').addEventListener('click',e=>{if(e.target===$('dialog')){const r=$('dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});document.querySelector('.close-dialog').onclick=closeDialog;
function showHelp(){openDialog('The railway field guide','<p class="dialog-intro">Build the network while time is paused. Start the clock when your first train is ready.</p><div class="help-grid"><article><h3>1. Survey and build</h3><p>Select Build. Choose two sites on the map or in the lists. Follow the valley for gentle grades. Review the quote, then lay the railway.</p><p>Each site serves its local town or industry. New stations are included in the quoted price.</p></article><article><h3>2. Give trains a purpose</h3><p>Open Trains and buy a locomotive. Select two to four connected stops. The train repeats them in order.</p><p>Automatic cargo loads goods accepted at the next stop. Passengers can travel between all three towns.</p></article><article><h3>3. Complete the chains</h3><p>Carry logs from Highpine to Pineworks. Then carry lumber to Port Alder. Use a three-stop train for both deliveries.</p><p>Grain makes food at Millbrook. Ore makes copper at Alder Foundry. The port buys both finished goods.</p></article><article><h3>4. Keep trains moving</h3><p>Single track gives one train ownership of a link. Other trains wait at a signal. Add double track to increase capacity.</p><p>Depots service trains below 82% condition. Manual service costs $5k. Poor condition reduces speed.</p></article><article><h3>5. Protect the company</h3><p>Traffic and industry income pay running costs and interest. Contract grants add cash separately. Bond money and share issues are funding.</p><p>The railway fails if its cash reaches −$100k. Borrow before that point, or sell unused engines.</p></article><article><h3>6. Earn the charter</h3><p>Complete all bronze goals with non-negative cash. You can claim the charter or continue for silver and gold.</p><p>All higher awards include the lower goals. The deadline is January 1900. Free play is available after the result.</p></article></div><h3 class="section-title">Controls</h3><div class="shortcuts"><span>Pause or run <kbd>Space</kbd></span><span>Move map <kbd>Drag / WASD / arrows</kbd></span><span>Zoom <kbd>Wheel / + / −</kbd></span><span>Build railway <kbd>B</kbd></span><span>Buy a locomotive <kbd>T</kbd></span><span>Company accounts <kbd>C</kbd></span><span>Charter goals <kbd>G</kbd></span><span>Close a panel or menu <kbd>Esc</kbd></span></div><p class="data-note">Save games and preferences stay in this browser. Use Export save in the game menu to keep a separate copy.</p><div class="form-actions"><button class="primary" data-action="close">Back to the valley</button></div>','A PRACTICAL GUIDE');}
function showCredits(){openDialog('Credits & research','<div class="credits"><p><strong>Copperline: A Valley in Motion</strong> is an original railway strategy game. Its map, engines, rules, interface, music, and game art were created for this level.</p><p><strong>Engine foundation:</strong> <a href="https://github.com/michaelcrosato/my-3d2dge/blob/main/engine/my-3d2dge-agent.js" target="_blank" rel="noreferrer">my-3D2dge Agent Edition v0.12.1</a> by Michael Crosato. The engine provides the game loop, view projection, depth queue, camera, audio, and storage helpers. It is used under the <a href="engine/LICENSE.txt" target="_blank">MIT license</a>.</p><p><strong>Design research:</strong> <a href="https://manualmachine.com/gamespc/railroadtycooniiplatinum/1118901-user-manual/" target="_blank" rel="noreferrer">Railroad Tycoon II: Platinum manual</a>, <a href="https://steamcommunity.com/sharedfiles/filedetails/?id=314464865" target="_blank" rel="noreferrer">Bole’s fan strategy guide</a>, and <a href="https://gamefaqs.gamespot.com/pc/198394-railroad-tycoon-ii/faqs/20897" target="_blank" rel="noreferrer">Joe Kennedy’s strategy guide</a>.</p><p><em>Railroad Tycoon II</em> inspired the connection between railway operations, geography, and business decisions. Copperline uses original content and does not contain source-game assets.</p><p><strong>Art:</strong> Original generated key art. The playable valley, vehicles, buildings, and effects are drawn by code. The music and sound effects are synthesized at runtime.</p><p><strong>Visual processing:</strong> The optional WebGPU pass uses color quantization, image edges, and a pixel grid. The settings identify the active renderer. Standard graphics remain available.</p><p class="fineprint">Version 1.0 · The Valley Charter · Single-player browser edition.</p></div>','THE PEOPLE & IDEAS BEHIND THE VALLEY');}
function showSettings(){const radio=(val,label)=>'<button data-filter-mode="'+val+'" class="'+(settings.mode===val?'selected':'')+'">'+label+'</button>';const range=(key,label,min,max,step)=>'<div class="range-row"><label for="setting-'+key+'">'+label+'<output id="value-'+key+'">'+settings[key]+'</output></label><input id="setting-'+key+'" type="range" data-setting="'+key+'" min="'+min+'" max="'+max+'" step="'+step+'" value="'+settings[key]+'"></div>';
 openDialog('Make the valley your own','<div class="setting-group"><h3>Art style</h3><div class="segmented">'+radio('standard','Standard')+radio('cel','Cel shading')+radio('pixel','Pixel art')+'</div><label class="check" style="margin:18px 0"><input type="checkbox" data-setting="gpu" '+(settings.gpu?'checked':'')+'> Use WebGPU when available</label><div id="render-status" class="render-status">Active renderer: '+filter.backend+'. '+(filter.failed?'WebGPU is unavailable. The compatibility filter is active.':'')+'</div><div class="settings-grid">'+range('bands','Color bands',3,16,1)+range('edge','Ink edge strength',0,3,.1)+range('pixel','Pixel size',2,12,1)+range('dither','Dither amount',0,1,.01)+range('saturation','Saturation',.5,1.8,.05)+range('strength','Filter strength',0,1,.05)+'</div><p class="fineprint">Color bands, saturation, and strength affect both filters. Ink edges affect cel shading. Pixel size and dither affect pixel art. The interface stays sharp.</p></div><div class="setting-group"><h3>Sound & motion</h3>'+range('volume','Master volume',0,1,.05)+'<div class="settings-grid"><label class="check"><input type="checkbox" data-setting="music" '+(settings.music?'checked':'')+'> Valley music</label><label class="check"><input type="checkbox" data-setting="effects" '+(settings.effects?'checked':'')+'> Railway sounds</label></div><label class="check" style="margin-top:20px"><input type="checkbox" data-setting="reduced" '+(settings.reduced?'checked':'')+'> Reduce decorative motion</label></div><div class="form-actions"><button class="secondary" data-action="reset-settings">Reset settings</button><button class="primary" data-action="close">Return to the valley</button></div>','GRAPHICS, SOUND & ACCESSIBILITY');}
let trainDraft=null;
function openTrain(id=null){const t=id?sim.trains.find(t=>t.id===id):null;const stations=sim.sites.filter(s=>s.station);if(stations.length<2||!sim.routes.length){toast('Build a railway first','A train needs at least two connected stations.','warning');selectTab('build');return;}
 trainDraft={id:t?.id,engine:t?.engine||'pioneer',stops:t?[...t.stops]:[sim.routes[0].from,sim.routes[0].to],cars:t?.cars||4,cargo:t?.cargo||'auto',wait:t?.wait||'any',name:t?.name||''};renderTrainForm();}
function renderTrainForm(){const d=trainDraft,edit=!!d.id,e=ENGINES[d.engine];const engines=Object.entries(ENGINES).map(([id,e])=>'<button type="button" class="engine-choice '+(d.engine===id?'selected':'')+'" data-engine="'+id+'" '+(edit||sim.month<e.available?'disabled':'')+'><span class="engine-title"><strong>'+e.name+'</strong><span>'+money(e.price)+'</span></span><p>'+e.description+'</p><span class="engine-spec"><span>'+e.speed+' km/month</span><span>'+e.capacity+' cars</span><span>'+money(e.upkeep,2)+'/mo</span></span></button>').join('');const options=selected=>sim.sites.filter(s=>s.station).map(s=>'<option value="'+s.id+'" '+(s.id===selected?'selected':'')+'>'+s.name+'</option>').join('');
 const html='<p class="dialog-intro">Choose connected stops in travel order. The train repeats this list. Automatic cargo serves the next stop.</p><form id="train-form"><div class="form-grid"><div><h3>Choose your engine</h3>'+engines+'<label class="field"><span>Train name (optional)</span><input type="text" maxlength="32" id="train-name" value="'+esc(d.name)+'" placeholder="Name your service"></label>'+(!edit?'<label class="field"><span>Number of cars · $2k each</span><select id="train-cars">'+Array.from({length:e.capacity},(_,i)=>'<option '+(d.cars===i+1?'selected':'')+' value="'+(i+1)+'">'+(i+1)+' cars</option>').join('')+'</select></label>':'')+'</div><div><h3>Route & cargo</h3>'+d.stops.map((s,i)=>'<div class="stop-row"><label class="field"><span>Stop '+(i+1)+'</span><select data-stop="'+i+'">'+options(s)+'</select></label>'+(i>1?'<button type="button" class="remove-stop" data-remove-stop="'+i+'" aria-label="Remove stop '+(i+1)+'">×</button>':'')+'</div>').join('')+(d.stops.length<4?'<button class="mini-btn" type="button" data-action="add-stop">+ Add stop</button>':'')+'<label class="field"><span>Cargo plan</span><select id="train-cargo"><option value="auto">Automatic · match next stop</option>'+Object.entries(GOODS).map(([k,g])=>'<option value="'+k+'" '+(d.cargo===k?'selected':'')+'>'+g.name+' only</option>').join('')+'</select></label><label class="field"><span>Departure rule</span><select id="train-wait">'+[['any','Any available cargo'],['half','Wait for half a load'],['full','Wait for a full load']].map(([k,l])=>'<option value="'+k+'" '+(d.wait===k?'selected':'')+'>'+l+'</option>').join('')+'</select></label><div class="tip">Trains wait for no more than one month. A service depot improves reliability. Single track may cause signal waits.</div><div class="cost-total"><span>'+(edit?'Order changes':'Engine and cars')+'</span><strong>'+(edit?'No charge':money(e.price+d.cars*2))+'</strong></div></div></div><div id="train-error" class="form-error" role="alert"></div><div class="form-actions"><button type="button" class="secondary" data-action="close">Cancel</button><button type="submit" class="primary">'+(edit?'Save new orders':'Buy and dispatch')+'</button></div></form>';
 openDialog(edit?'New orders':'A new engine for the valley',html,'LOCOMOTIVE WORKS');$('train-form').onsubmit=event=>{event.preventDefault();try{readTrainDraft();let t;if(edit){sim.configureTrain(d.id,d);t=sim.trains.find(t=>t.id===d.id);}else t=sim.buyTrain(d);closeDialog();selectTrain(t.id);sfx('powerup',.35);toast(edit?'Orders saved':'Train ready',edit?'The train will apply the orders at the next shared stop.':'Start the clock to begin service.');save(false);}catch(e){$('train-error').textContent=e.message;}};
}
function readTrainDraft(){if(!trainDraft)return;const d=trainDraft;if($('train-name'))d.name=$('train-name').value;if($('train-cars'))d.cars=Number($('train-cars').value);if($('train-cargo'))d.cargo=$('train-cargo').value;if($('train-wait'))d.wait=$('train-wait').value;document.querySelectorAll('[data-stop]').forEach(el=>d.stops[+el.dataset.stop]=el.value);}
function save(explicit=true){if(!ui.started)return;try{const payload={game:sim.serialize(),ui:{showGuide:ui.showGuide,speed:ui.speed},savedAt:new Date().toISOString()};localStorage.setItem('copperline-save-v1',JSON.stringify(payload));$('save-status').textContent='Saved '+new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'});if(explicit)toast('Railway saved','Your game is saved in this browser.');$('continue-button').hidden=false;ui.saveAge=0;return payload;}catch(e){$('save-status').textContent='Save unavailable';if(explicit)toast('Could not save','Export a save file from the game menu.','warning');return {game:sim.serialize(),ui:{showGuide:ui.showGuide,speed:ui.speed}};}}
function getSave(){try{const s=localStorage.getItem('copperline-save-v1');return s?JSON.parse(s):null;}catch{return null;}}
function startGame(load=false){let payload=load?getSave():null;if(load&&!payload){toast('No saved railway','Begin a new charter to start.');return;}try{sim=new Railway(payload?.game);ui.started=true;$('game-shell').inert=false;ui.paused=true;ui.speed=payload?.ui?.speed||1;ui.showGuide=payload?payload.ui.showGuide:$('tutorial-choice').checked;ui.outcomeShown=false;ui.acc=0;world.reset();world.quote=null;world.bursts=[];world.smoke=[];$('title-screen').hidden=true;closeDialog();selectTab('overview');if(settings.music)game.audio.music(score);if(!load)save(false);else if(sim.result)showResult();sfx('confirm',.4);}catch(e){toast('Save could not be opened',e.message,'warning');}}
function exportSave(){const data=save(false)||{game:sim.serialize()};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='copperline-'+date(sim.month).toLowerCase().replace(' ','-')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function showMenu(){if(!ui.started){$('title-screen').hidden=false;return;}openDialog('Railway office','<p class="dialog-intro">'+date(sim.month)+' · '+money(sim.cash)+' cash · '+sim.trains.length+' trains. The clock is paused while this menu is open.</p><div class="help-grid"><button class="primary" data-action="close">Return to the railway</button><button class="secondary" data-action="save">Save this railway</button><button class="secondary" data-action="export">Export save</button><button class="secondary" data-action="import">Import save</button><button class="secondary" data-action="settings">Settings</button><button class="secondary" data-action="help">Open field guide</button></div><div class="danger-zone"><button class="danger-btn" data-action="restart">Begin a new charter</button><button class="link-button" style="margin-left:17px" data-action="title">Main menu</button><button class="link-button" style="margin-left:17px" data-action="credits">Credits & research</button></div>','COMPANY OFFICE');}
function confirmAction(title,text,action){openDialog(title,'<p class="dialog-intro">'+esc(text)+'</p><div class="form-actions"><button class="secondary" data-action="close">Cancel</button><button class="danger-btn" id="confirm-action">Confirm</button></div>');$('confirm-action').onclick=()=>{closeDialog();act(action);};}
function showResult(){if(!sim.result||ui.outcomeShown)return;ui.outcomeShown=true;ui.paused=true;const result=sim.result;const goals=sim.goals();const missed=goals.bronze.filter(g=>g.value<g.target);openDialog(result.won?'The valley has its railway':'The charter has closed','<div class="outcome"><div class="award">'+(result.won?'✧':'◇')+'</div><span class="eyebrow">'+(result.won?result.medal.toUpperCase()+' CHARTER AWARDED':'CHARTER NOT AWARDED')+'</span><h3 style="margin-top:12px">'+(result.won?'A valley, connected.':'Every railway starts with a lesson.')+'</h3><p>'+(result.won?'Your railway connects people, work, and markets. The charter board has approved your company.':esc(result.reason||'The charter goals were not met.'))+'</p><div class="outcome-stats"><div><strong>'+money(sim.profit)+'</strong><span>Operating profit</span></div><div><strong>'+sim.connected.length+' / 8</strong><span>Sites connected</span></div><div><strong>'+money(sim.companyValue)+'</strong><span>Company value</span></div><div><strong>'+(sim.delivered.passengers||0)+'</strong><span>Passenger cars</span></div><div><strong>'+money(sim.debt)+'</strong><span>Remaining debt</span></div><div><strong>'+date(sim.month)+'</strong><span>Final date</span></div></div>'+(missed.length?'<p style="margin-top:17px">Goals still open: '+missed.map(g=>esc(g.label)).join('; ')+'.</p>':'')+'<div class="form-actions"><button class="secondary" data-action="restart">Play the charter again</button><button class="primary" data-action="freeplay">Continue in free play</button></div></div>','THE CHARTER BOARD');sfx(result.won?'powerup':'die',.4);save(false);}
$('import-file').addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;try{if(f.size>2*1024*1024)throw new Error('The save file is too large.');const data=JSON.parse(await f.text()),next=new Railway(data.game||data);sim=next;ui.started=true;$('game-shell').inert=false;ui.paused=true;ui.acc=0;ui.outcomeShown=false;$('title-screen').hidden=true;world.reset();world.quote=null;closeDialog();selectTab('overview');save(false);toast('Railway restored','The imported game is ready.');if(sim.result)showResult();}catch(e){toast('Save could not be opened',e.message,'warning');}e.target.value='';});
function action(name,el){switch(name){case 'new-game':if(getSave())confirmAction('Begin a new charter?','This replaces the saved railway in this browser. Export it first if you want to keep it.',()=>startGame(false));else startGame(false);break;case 'continue':startGame(true);break;case 'settings':showSettings();break;case 'help':showHelp();break;case 'credits':showCredits();break;case 'close':closeDialog();break;case 'home':showMenu();break;case 'title':save(false);closeDialog();ui.started=false;ui.paused=true;$('game-shell').inert=true;$('title-screen').hidden=false;game.audio.music(null);break;case 'restart':confirmAction('Begin a new charter?','Your current railway will be replaced. Export a save first if you want to keep it.',()=>startGame(false));break;case 'save':save();break;case 'export':exportSave();break;case 'import':$('import-file').click();break;case 'freeplay':sim.result=null;sim.sandbox=true;ui.outcomeShown=false;closeDialog();ui.paused=false;ui.dirty=true;toast('Free play','Build at your own pace. The charter deadline is removed.');break;case 'pause':if(ui.started&&!sim.result){ui.paused=!ui.paused;ui.dirty=true;sfx('pause',.15);}break;case 'zoom-in':world.setZoom(world.camera.zoom+.2);break;case 'zoom-out':world.setZoom(world.camera.zoom-.2);break;case 'reset-view':world.reset();break;case 'layers':world.overlay=world.overlay==='normal'?'terrain':world.overlay==='terrain'?'cargo':'normal';$('layer-toggle').textContent={normal:'Terrain',terrain:'Cargo',cargo:'Standard'}[world.overlay];break;case 'tab-build':selectTab('build');break;case 'build-route':act(()=>{const r=sim.buildRoute(world.quote);world.quote=null;ui.from=r.to;ui.to=null;ui.tab='routes';sfx('door',.3);save(false);return r;});break;case 'buy-train':openTrain();break;case 'claim':act(()=>{sim.finish();showResult();});break;case 'hide-guide':ui.showGuide=false;ui.dirty=true;break;case 'station':act(()=>sim.buildStation(el.dataset.id));break;case 'connect-site':ui.from=el.dataset.id;ui.to=null;selectTab('build');break;case 'buy-industry':act(()=>sim.buyIndustry(el.dataset.id));break;case 'expand-industry':act(()=>sim.upgradeIndustry(el.dataset.id));break;case 'bond':act(()=>sim.issueBond());break;case 'repay':act(()=>sim.repayBond());break;case 'issue-shares':act(()=>sim.issueShares());break;case 'buy-shares':act(()=>sim.buyShares());break;case 'sell-shares':act(()=>sim.sellShares());break;case 'sell-train':{const id=el.dataset.id,t=sim.trains.find(t=>t.id===id);confirmAction('Sell '+t.name+'?','The engine and its current cargo will leave the railway. The sale returns part of its purchase value.',()=>{sim.sellTrain(id);selectTab('trains');});break;}case 'add-stop':readTrainDraft();{const next=sim.sites.find(s=>s.station&&!trainDraft.stops.includes(s.id));if(next){trainDraft.stops.push(next.id);renderTrainForm();}else toast('No other station','Build another station before you add a stop.');}break;case 'reset-settings':settings={mode:'standard',gpu:true,bands:10,edge:.8,pixel:4,dither:.18,saturation:1.05,strength:.75,volume:.4,music:true,effects:true,reduced:matchMedia('(prefers-reduced-motion:reduce)').matches};applySettings();showSettings();break;}}
document.addEventListener('click',event=>{const el=event.target.closest('button');if(!el||el.disabled)return;
 if(el.dataset.action)action(el.dataset.action,el);
 if(el.dataset.tab)selectTab(el.dataset.tab);
 if(el.dataset.site)selectSite(el.dataset.site);
 if(el.dataset.train)selectTrain(el.dataset.train);
 if(el.dataset.speed){ui.speed=Number(el.dataset.speed);if(ui.started&&!sim.result)ui.paused=false;ui.dirty=true;}
 if(el.dataset.policy){ui.policy=el.dataset.policy;updateSurvey();}
 if(el.dataset.double)act(()=>sim.doubleTrack(el.dataset.double));
 if(el.dataset.removeRoute){const id=el.dataset.removeRoute;confirmAction('Remove this railway?','The company recovers 35% of the track cost. A railway that is needed by a train cannot be removed.',()=>sim.removeRoute(id));}
 if(el.dataset.upgradeStation)act(()=>sim.upgradeStation(el.dataset.upgradeStation));
 if(el.dataset.serviceSite)act(()=>sim.addService(el.dataset.serviceSite));
 if(el.dataset.follow){world.follow=world.follow===el.dataset.follow?null:el.dataset.follow;world.setZoom(1.6);ui.dirty=true;}
 if(el.dataset.hold)act(()=>{const t=sim.trains.find(t=>t.id===el.dataset.hold);t.hold=!t.hold;});
 if(el.dataset.serviceTrain)act(()=>sim.serviceTrain(el.dataset.serviceTrain));
 if(el.dataset.orders)openTrain(el.dataset.orders);
 if(el.dataset.engine){readTrainDraft();trainDraft.engine=el.dataset.engine;trainDraft.cars=Math.min(trainDraft.cars,ENGINES[trainDraft.engine].capacity);renderTrainForm();}
 if(el.dataset.removeStop){readTrainDraft();trainDraft.stops.splice(+el.dataset.removeStop,1);renderTrainForm();}
 if(el.dataset.filterMode){settings.mode=el.dataset.filterMode;applySettings();document.querySelectorAll('[data-filter-mode]').forEach(b=>b.classList.toggle('selected',b.dataset.filterMode===settings.mode));}
 updateUI();
});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='build-from'){ui.from=t.value;updateSurvey();updateUI(true);}if(t.id==='build-to'){ui.to=t.value;updateSurvey();updateUI(true);}if(t.id==='dividend')act(()=>sim.setDividend(+t.value));if(t.dataset.setting){settings[t.dataset.setting]=t.type==='checkbox'?t.checked:+t.value;applySettings();}if(t.id==='train-cars'){readTrainDraft();renderTrainForm();}});
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.setting){const key=t.dataset.setting;settings[key]=t.type==='checkbox'?t.checked:+t.value;if($('value-'+key))$('value-'+key).textContent=settings[key];game.audio.setVolume(settings.volume);world.reduced=settings.reduced;filter.apply(settings);E.store.set('copperline-settings-v1',settings);}});
const keys=new Set();document.addEventListener('keydown',e=>{if(e.target.closest('input,select,textarea,button,[contenteditable=true]'))return;if(e.code==='Escape'){if(ui.modal){closeDialog();return;}if(ui.tab==='build'){selectTab('overview');return;}showMenu();return;}if(ui.modal||!ui.started)return;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Equal','Minus'].includes(e.code))e.preventDefault();keys.add(e.code);if(e.repeat)return;switch(e.code){case'Space':action('pause');break;case'KeyB':selectTab('build');break;case'KeyT':openTrain();break;case'KeyC':selectTab('company');break;case'KeyG':selectTab('goals');break;case'Slash':showHelp();break;case'Equal':world.setZoom(world.camera.zoom+.15);break;case'Minus':world.setZoom(world.camera.zoom-.15);break;}updateUI();});document.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>keys.clear());
let drag=null;const canvas=$('world');canvas.addEventListener('pointerdown',e=>{if(e.button!==0&&e.button!==1)return;canvas.setPointerCapture(e.pointerId);drag={x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,moved:false};});canvas.addEventListener('pointermove',e=>{if(drag){const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)>4)drag.moved=true;if(drag.moved){world.moveScreen(dx,dy);canvas.classList.add('dragging');}drag.x=e.clientX;drag.y=e.clientY;}else{const hit=world.pickup(e.clientX,e.clientY);world.hover=hit?.type==='site'?hit.id:null;canvas.style.cursor=hit?'pointer':ui.tab==='build'?'crosshair':'grab';}});canvas.addEventListener('pointerup',e=>{if(drag&&!drag.moved){const hit=world.pickup(e.clientX,e.clientY);if(hit?.type==='site')selectSite(hit.id);if(hit?.type==='train')selectTrain(hit.id);}drag=null;canvas.classList.remove('dragging');});canvas.addEventListener('pointercancel',()=>{drag=null;canvas.classList.remove('dragging');});canvas.addEventListener('wheel',e=>{e.preventDefault();world.setZoom(world.camera.zoom*Math.exp(-e.deltaY*.0012));},{passive:false});$('minimap').addEventListener('pointerdown',e=>{const r=e.target.getBoundingClientRect();world.camera.x=(e.clientX-r.left)/r.width*W*TILE;world.camera.y=(e.clientY-r.top)/r.height*H*TILE;world.follow=null;});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&ui.started){ui.paused=true;save(false);}});window.addEventListener('pagehide',()=>save(false));
let hudTimer=0,panelTimer=0,lastFrameAt=performance.now(),actualFrameMs=0;
game.start({update(dt){world.update(dt);if(ui.started&&!ui.modal){const step=dt*200;if(keys.has('KeyA')||keys.has('ArrowLeft'))world.moveScreen(step,0);if(keys.has('KeyD')||keys.has('ArrowRight'))world.moveScreen(-step,0);if(keys.has('KeyW')||keys.has('ArrowUp'))world.moveScreen(0,step);if(keys.has('KeyS')||keys.has('ArrowDown'))world.moveScreen(0,-step);}
 if(ui.started&&!ui.paused&&!ui.modal&&!sim.result){ui.acc+=dt*ui.speed/MONTH_SECONDS;const fixed=1/120;while(ui.acc+1e-10>=fixed){sim.advance(fixed);ui.acc-=fixed;if(sim.result){ui.acc=0;break;}}}
 if(ui.started){ui.saveAge+=dt;if(ui.saveAge>20)save(false);while(sim.notifications.length){const n=sim.notifications.shift();if(n.type==='delivery'){world.delivery(n.site,n.amount);sfx('coin',.08);}else{toast(n.title,n.text,n.type);sfx(n.type==='contract'?'powerup':n.type==='warning'?'cancel':'select',.2);}ui.dirty=true;}
 if(sim.result&&!ui.outcomeShown)showResult();const medal=sim.medal();if(medal&&medal!==ui.lastMedal){ui.lastMedal=medal;toast('Charter award ready','You have met the '+medal+' goals. Claim the charter in Awards.','contract');}}
 hudTimer+=dt;panelTimer+=dt;if(hudTimer>.25){hudTimer=0;if(panelTimer>1.5){panelTimer=0;if(['site','train','trains','company','goals','overview'].includes(ui.tab))ui.dirty=true;}updateUI();}
 },draw(r){const now=performance.now();actualFrameMs=actualFrameMs*.9+(now-lastFrameAt)*.1;lastFrameAt=now;if(ui.started)world.draw(r);$('world').dataset.frameMs=actualFrameMs.toFixed(1);$('world').dataset.renderMs=game.stats.renderMs.toFixed(1);}});
$('continue-button').hidden=!getSave();applySettings();renderPanel();updateUI();
// Read-only diagnostics and the same visible game commands support repeatable QA.
window.Copperline={version:'1.0.0',get sim(){return sim},game,world,filter,ui,settings,startGame,selectTab,selectSite,selectTrain,openTrain,showSettings,save,updateUI};
const context=document.modelContext;if(context?.registerTool){const lifecycle=new AbortController();const tools=[{name:'read_railway_state',description:'Read the current railway, funds, deliveries, and charter goals.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({date:date(sim.month),cash:sim.cash,debt:sim.debt,goals:sim.goals(),trains:sim.trains.map(t=>({id:t.id,name:t.name,stops:t.stops,status:status(t)})),routes:sim.routes.map(r=>({id:r.id,from:r.from,to:r.to}))})},{name:'survey_railway',description:'Stage a route survey in the visible Build panel. This does not spend company cash.',inputSchema:{type:'object',properties:{from:{type:'string',enum:SITES.map(s=>s.id)},to:{type:'string',enum:SITES.map(s=>s.id)}},required:['from','to'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['from','to'].includes(k)))throw new Error('Invalid input');const quote=sim.survey(input.from,input.to);ui.from=input.from;ui.to=input.to;ui.policy='valley';selectTab('build');updateUI(true);return {cost:quote.cost,length:quote.length,bridges:quote.bridges,staged:true};}}];for(const tool of tools)try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
